382: function applyMove(attacker, defender, move, done) {
383:   if(!battle||battle.finished)return
384:   const status=battle.status[attacker]
385:   if(status.staggered) {
386:     status.staggered=false
387:     battle.guard[attacker]=false
388:     battle.sta[attacker]=Math.min(battle.maxSta[attacker],battle.sta[attacker]+8)
389:     toast(`${battle[attacker].name} is staggered and loses the turn.`)
390:     done(); return
391:   }
392:   if(move.type==='defend') {
393:     battle.guard[attacker]=true; battle.sta[attacker]=Math.min(battle.maxSta[attacker],battle.sta[attacker]+Math.abs(move.cost));
394:     toast(`${battle[attacker].name} braces and recovers stamina.`); done(); return
395:   }
396:   const cost=Math.max(0,move.cost)
397:   if(battle.sta[attacker]<cost) { battle.sta[attacker]=Math.min(battle.maxSta[attacker],battle.sta[attacker]+12); toast(`${battle[attacker].name} is winded and recovers 12 stamina.`); done(); return }
398:   battle.sta[attacker]-=cost
399:   const accuracy=Math.max(0.1,move.acc-(status.accuracyDown?0.25:0))
400:   status.accuracyDown=false
401:   if(Math.random()>accuracy) { toast(`${move.name} missed!`); done(); return }
