  hud.innerHTML=`${bar('player','YOUR CREATURE')}<div class="battle-turn">${center}</div>${bar('foe',battle.challenge?(battle.challenge.boss?'APEX BOSS':'WILD CHALLENGER'):'OPPONENT')}`
