}
function copyGenome(genome) {
  return Object.fromEntries(GENES.map(g => {
    const alleles = genome?.[g.key] || [0.5, 0.5]
    return [g.key, [clamp(Number(alleles[0]) || 0, 0, 1), clamp(Number(alleles[1]) || 0, 0, 1)]]
  }))
}
